#!/usr/bin/env bash
# AKFC — Builder : infobulles et palette de surlignage RÉELLEMENT fonctionnelles.
#  Constat (navigateur, éditeur réel) : le composant d'infobulle du gabarit Tiptap
#  (@floating-ui/react) ne s'ouvrait jamais (ni survol, ni focus) ; et, posé sur le bouton
#  « Surligner », il empêchait Radix de positionner la palette, restée HORS ÉCRAN (y = -92 px).
#  Correctif :
#  - ui-primitive/tooltip : réécrit sur Radix Tooltip (même API, aucun appelant à modifier) ;
#  - ui-primitive/button : infobulle aussi sur les boutons DÉSACTIVÉS (la barre en désactive
#    la plupart tant que le curseur n'est pas dans le texte).
#  Vérifié dans Chromium : infobulles « Gras », « Italique », « Surligner », « Centrer »,
#  « Annuler » (même désactivé) ; palette ouverte sous le bouton ; surlignage jaune appliqué.
#  Prérequis : fix-builder-tooltips-highlight.sh (libellés FR + variables CSS).
#  Preuve avant commit : pnpm check (sinon TOUT est restauré).
# Usage : bash fix-builder-tooltips-radix.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
T="apps/web/src/features/editor-tiptap/ui-primitive/tooltip/tooltip.tsx"; BT="apps/web/src/features/editor-tiptap/ui-primitive/button/button.tsx"
[ -f apps/web/src/styles/tiptap-variables.css ] || { echo "ERREUR: applique d'abord fix-builder-tooltips-highlight.sh." >&2; exit 1; }
grep -q "Radix Tooltip" "$T" && { echo "— déjà appliqué"; exit 0; }
[ "$(sha256sum "$T" | cut -c1-64)" = "50dff3845cd295f430acabe5e1c6871fbe3a895f19fdae4d91c21848aaf0fdbb" ] || { echo "ERREUR: $T a été modifié — rien n'est touché. Envoie-le moi." >&2; exit 1; }
BK=/tmp/akfc_ttr_backup; rm -rf "$BK"; mkdir -p "$BK"; cp "$T" "$BK/t"; cp "$BT" "$BK/b"
restore(){ cp "$BK/t" "$T"; cp "$BK/b" "$BT"; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }
W=/tmp/akfc_ttr; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/edit.py"
echo '' | base64 -d > "$W/old.txt"
echo '' | base64 -d > "$W/new.txt"
echo "== application =="
echo '' | base64 -d > "$T" && echo "  ok  infobulle réécrite sur Radix"
python3 "$W/edit.py" . "$W/old.txt" "$W/new.txt" || { restore; exit 1; }
if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi
echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"
git add "$T" "$BT"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
fix(builder): infobulles sur Radix (s'ouvrent enfin) et palette de surlignage positionnée

